import{_ as e,o as a,c as i,a2 as s}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Mitigation Overview","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/mitigation/overview.md","filePath":"openshield-xdp/mitigation/overview.md","lastUpdated":1782795623000}'),d={name:"openshield-xdp/mitigation/overview.md"};function n(r,t,o,l,p,c){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="mitigation-overview" tabindex="-1">Mitigation Overview <a class="header-anchor" href="#mitigation-overview" aria-label="Permalink to &quot;Mitigation Overview&quot;">​</a></h1><p>When an IP&#39;s suspicion score reaches the effective threshold, OpenShield automatically bans it. Multiple escalation mechanisms tighten response for repeat offenders and subnet-level attacks. The <strong>Bloom filter</strong> accelerates whitelist lookups, and <strong>freplace hot-patching</strong> enables live updates to mitigation stages without reloading the XDP program.</p><h2 id="ban-types" tabindex="-1">Ban types <a class="header-anchor" href="#ban-types" aria-label="Permalink to &quot;Ban types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Mechanism</th><th>Duration</th></tr></thead><tbody><tr><td>Single-IP</td><td>Inserted when <code>suspicion_score ≥ effective_threshold</code></td><td><code>ban_duration * star_multiplier</code> (default 1 hour)</td></tr><tr><td>LPM subnet</td><td>CIDR-level via longest-prefix-match trie</td><td><code>subnet_ban_duration</code> (default 2 hours)</td></tr><tr><td>Auto /24 escalation</td><td>After N single-IP bans per /24</td><td><code>ban_duration * 2</code></td></tr><tr><td>Auto /64 escalation</td><td>After N single-IP bans per /64 (IPv6)</td><td><code>ban_duration * 2</code></td></tr><tr><td>Star (repeat)</td><td>6 offense levels, multipliers ×1–×32</td><td><code>ban_duration * star_multiplier</code></td></tr></tbody></table><h2 id="ban-reason-codes" tabindex="-1">Ban reason codes <a class="header-anchor" href="#ban-reason-codes" aria-label="Permalink to &quot;Ban reason codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Trigger</th><th>Description</th></tr></thead><tbody><tr><td>1</td><td><code>BAN_REASON_PPS</code></td><td>Packets/s exceeded</td></tr><tr><td>2</td><td><code>BAN_REASON_BPS</code></td><td>Bytes/s exceeded</td></tr><tr><td>3</td><td><code>BAN_REASON_TCP_PPS</code></td><td>TCP packets/s exceeded</td></tr><tr><td>4</td><td><code>BAN_REASON_UDP_PPS</code></td><td>UDP packets/s exceeded</td></tr><tr><td>5</td><td><code>BAN_REASON_ICMP_PPS</code></td><td>ICMP packets/s exceeded</td></tr><tr><td>6</td><td><code>BAN_REASON_SYN_PPS</code></td><td>SYN packets/s exceeded</td></tr><tr><td>7</td><td><code>BAN_REASON_NEW_SOURCE</code></td><td>New source flood</td></tr><tr><td>8</td><td><code>BAN_REASON_BOGUS_TCP</code></td><td>Bogus TCP flags</td></tr><tr><td>9</td><td><code>BAN_REASON_CONN_RATE</code></td><td>Connection rate limit</td></tr><tr><td>10</td><td><code>BAN_REASON_TTL_ANOMALY</code></td><td>TTL anomaly</td></tr><tr><td>11</td><td><code>BAN_REASON_PKT_ANOMALY</code></td><td>Packet size anomaly</td></tr><tr><td>12</td><td><code>BAN_REASON_ENTROPY</code></td><td>Entropy spoofing</td></tr><tr><td>13</td><td><code>BAN_REASON_SYN_FIN</code></td><td>SYN/FIN ratio</td></tr></tbody></table><p>The primary reason is determined by highest-weighted violation: SYN &gt; ICMP &gt; UDP &gt; TCP &gt; BPS &gt; PPS.</p><h2 id="star-system-repeat-offender-escalation" tabindex="-1">Star system: repeat offender escalation <a class="header-anchor" href="#star-system-repeat-offender-escalation" aria-label="Permalink to &quot;Star system: repeat offender escalation&quot;">​</a></h2><p>Six star levels with geometric duration multipliers:</p><table tabindex="0"><thead><tr><th>Star level</th><th><code>ban_count</code></th><th>Duration multiplier</th><th>Effective ban</th></tr></thead><tbody><tr><td>0 (first)</td><td>0</td><td>×1</td><td>1 hour</td></tr><tr><td>1</td><td>1</td><td>×2</td><td>2 hours</td></tr><tr><td>2</td><td>2</td><td>×4</td><td>4 hours</td></tr><tr><td>3</td><td>3</td><td>×8</td><td>8 hours</td></tr><tr><td>4</td><td>4</td><td>×16</td><td>16 hours</td></tr><tr><td>5 (max)</td><td>5+</td><td>×32</td><td>32 hours</td></tr></tbody></table><h3 id="star-decay" tabindex="-1">Star decay <a class="header-anchor" href="#star-decay" aria-label="Permalink to &quot;Star decay&quot;">​</a></h3><p>Stars decay by 1 level after a configurable clean period:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>star_decay_seconds = 3600 per star level</span></span></code></pre></div><p>Example: A star-3 (×8) IP that stays clean for 3 × 3600 = 10,800 seconds (3 hours) decays to star-2 (×4), then continues decaying hourly. The userspace ban manager handles star decay on its 5-second poll cycle.</p><h2 id="panic-circuit-breaker" tabindex="-1">Panic circuit breaker <a class="header-anchor" href="#panic-circuit-breaker" aria-label="Permalink to &quot;Panic circuit breaker&quot;">​</a></h2><p>A <strong>per-CPU probabilistic drop</strong> that activates when packet rate exceeds <code>panic_pps_rate</code> on any CPU:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Per-CPU panic bucket (PERCPU_ARRAY, no contention)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (pb</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">last_second </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> this_sec) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pb-&gt;pkt_count </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           // Reset window</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pb-&gt;last_second </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> this_sec;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pb</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pkt_count</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (pb</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pkt_count </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cfg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">panic_pps_rate) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Probabilistic drop at panic_drop_ratio %</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (cfg-&gt;panic_drop_ratio </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        (pb-&gt;pkt_count </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cfg-&gt;panic_drop_ratio) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> XDP_DROP;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Config field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>panic_pps_rate</code></td><td>200,000</td><td>Per-CPU PPS trigger (0 = disabled)</td></tr><tr><td><code>panic_drop_ratio</code></td><td>80</td><td>Percentage of packets to drop in panic mode</td></tr><tr><td><code>panic_global_pps_threshold</code></td><td>5,000,000</td><td>Global PPS threshold for coordinated panic (userspace-managed)</td></tr><tr><td><code>panic_coordination_enabled</code></td><td>true</td><td>Enable cross-CPU panic coordination</td></tr></tbody></table><p>The panic breaker runs before any per-IP checks (stage 3 in the pipeline). It acts as a <strong>last-resort bulkhead</strong>: when the CPU is overwhelmed, drop packets probabilistically rather than trying to track per-IP state (which would add overhead during overload).</p><div class="warning custom-block"><p class="custom-block-title">Panic breaker drops indiscriminately</p><p>Panic drops are <em>not</em> tracked per-IP. Legitimate traffic is dropped alongside attack traffic. Use only as a fail-safe — tune per-IP rate thresholds first. Set <code>panic_pps_rate: 0</code> to disable.</p></div><h2 id="freplace-hot-patching" tabindex="-1">freplace hot-patching <a class="header-anchor" href="#freplace-hot-patching" aria-label="Permalink to &quot;freplace hot-patching&quot;">​</a></h2><p>Five mitigation stages support <strong>runtime replacement</strong> via BPF freplace. This is <strong>opt-in</strong> (<code>make FREPLACE=1</code>, kernel ≥ 6.10, <code>CONFIG_DEBUG_INFO_BTF=y</code>); default builds inline these stages for universal kernel portability:</p><table tabindex="0"><thead><tr><th>Stage</th><th>freplace target</th><th>Can replace</th></tr></thead><tbody><tr><td>Ban check</td><td><code>SEC(&quot;freplace/stage_ban_check&quot;)</code></td><td>Single-IP + subnet ban logic, event emission</td></tr><tr><td>Rate limit</td><td><code>SEC(&quot;freplace/stage_rate_limit&quot;)</code></td><td>Threshold scoring or token bucket algorithm</td></tr><tr><td>Connection tracking</td><td><code>SEC(&quot;freplace/stage_conn_track&quot;)</code></td><td>Blind SYN-ACK/RST detection</td></tr><tr><td>UDP amplification</td><td><code>SEC(&quot;freplace/stage_amp_check&quot;)</code></td><td>Amplification detection rules</td></tr><tr><td>L7 filter</td><td><code>SEC(&quot;freplace/stage_l7_filter&quot;)</code></td><td>L7 signature matching</td></tr></tbody></table><p>An example ban check replacement at <code>ebpf/modules/ban_check_freplace.c</code> adds per-hit ringbuf event emission. To deploy a replacement:</p><ol><li>Compile with <code>make -C ebpf/modules</code></li><li>Attach via <code>FreplaceManager.AttachFreplace(&quot;stage_ban_check&quot;, &quot;path/to/ban_check.o&quot;)</code></li></ol><p>The main XDP program is <strong>never unloaded</strong> — freplace swaps the subprogram pointer atomically via <code>bpf_link</code>.</p><h2 id="whitelist" tabindex="-1">Whitelist <a class="header-anchor" href="#whitelist" aria-label="Permalink to &quot;Whitelist&quot;">​</a></h2><p>Per-IP flags with granular bypass:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Value</th><th>Effect</th></tr></thead><tbody><tr><td><code>WL_FULL_BYPASS</code></td><td><code>0x0000</code></td><td>Skip all checks, immediate <code>XDP_PASS</code></td></tr><tr><td><code>WL_SKIP_BAN</code></td><td><code>0x0001</code></td><td>Skip ban + subnet ban lookup</td></tr><tr><td><code>WL_SKIP_RATE</code></td><td><code>0x0002</code></td><td>Skip rate threshold checks</td></tr><tr><td><code>WL_SKIP_VALIDATION</code></td><td><code>0x0004</code></td><td>Skip L3/L4 validation (private/bogon/bogus TCP)</td></tr></tbody></table><p>A <strong>Bloom filter</strong> (3 hashes, 150K u64 entries, ~1% FPR) is checked before the HASH whitelist lookup. If the Bloom filter says &quot;definitely not present&quot;, the more expensive HASH lookup is skipped entirely, saving ~60–100ns per packet.</p><p>The <code>whitelist_empty</code> config flag skips ALL whitelist lookups when the map has 0 entries. Updated automatically after every config change.</p><div class="tip custom-block"><p class="custom-block-title">Empty-map fast path</p><p>When 0 whitelist entries exist, the whitelist lookup is skipped entirely. Same for bans (<code>bans_empty</code> flag). Updated automatically after every config change.</p></div><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><p><a href="/pingless-studios-docs/openshield-xdp/mitigation/bans">Ban System</a> · <a href="/pingless-studios-docs/openshield-xdp/mitigation/rate-limiting">Rate Limiting</a> · <a href="/pingless-studios-docs/openshield-xdp/mitigation/whitelist">Whitelist</a> · <a href="/pingless-studios-docs/openshield-xdp/detection-engine/overview">Detection Engine</a></p>`,34)])])}const g=e(d,[["render",n]]);export{k as __pageData,g as default};
